class view amendments.logic:
class Component extends DCLogic {
  state = {
    theme: this.props.benchTheme || 'harbour',
    bench: this.props.benchState || 'open',
    week: 1, filter: 'ALL', lbweek: 'W01',
    account: false, cards: false, idx: 0, flipped: false, openRow: null,
    recall: false, qi: 0, picked: null, checked: false, roundNo: 1,
    answered: 0, streak: 0, best: 0, rounds: 0, roundScore: 0, roundDone: false,
  };

  // Sample of the recall bank. The live bank is generated from every lesson the
  // class has covered — hundreds of questions; six are drawn per round.
  bank() {
    return [
      { topic: 'BREATHING AND GAS EXCHANGE', q: 'A plant in a dark cupboard is releasing carbon dioxide. Which of the three processes is it carrying out?', options: ['Breathing', 'Respiration', 'Gas exchange only', 'All three'], answer: 1, note: 'Plants respire day and night; they do not breathe.' },
      { topic: 'PRESSURE', q: 'A fixed amount of gas is squeezed into half the space. What happens to its pressure?', options: ['It halves', 'It doubles', 'It stays the same', 'It drops to zero'], answer: 1, note: 'Same particles, smaller space, more collisions.' },
      { topic: 'GAS EXCHANGE', q: 'Which feature would make a gas exchange surface worse?', options: ['Thick walls', 'A large surface area', 'A good blood supply', 'A moist surface'], answer: 0, note: 'Thick walls make the diffusion distance longer — thin walls keep it short.' },
      { topic: 'CHEMICAL REACTIONS', q: 'Magnesium burns in oxygen. What is the product?', options: ['Magnesium oxide', 'Magnesium hydroxide', 'Magnesium carbonate', 'Magnesium chloride'], answer: 0, note: 'Metal + oxygen gives a metal oxide.' },
      { topic: 'PARTICLE MODEL', q: 'Which state has particles close together that can still move past each other?', options: ['Solid', 'Liquid', 'Gas', 'None of them'], answer: 1, note: 'Close packed, but not fixed in place.' },
      { topic: 'PRESSURE', q: 'A force of 20 N presses on 4 m2. What is the pressure?', options: ['5 Pa', '80 Pa', '24 Pa', '0.2 Pa'], answer: 0, note: 'p = F / A, so 20 / 4.' },
      { topic: 'GAS EXCHANGE', q: 'Where in the lungs does gas exchange happen?', options: ['The trachea', 'The bronchi', 'The alveoli', 'The diaphragm'], answer: 2, note: 'Millions of tiny air sacs, each with a thin wall.' },
      { topic: 'CHEMICAL REACTIONS', q: 'What is always conserved in a chemical reaction?', options: ['Mass', 'Colour', 'Volume', 'Temperature'], answer: 0, note: 'No atoms are made or lost, only rearranged.' },
    ];
  }

  round() {
    const bank = this.bank();
    const start = ((this.state.roundNo - 1) * 6) % bank.length;
    return Array.from({ length: 6 }, (_, i) => bank[(start + i) % bank.length]);
  }

  componentDidUpdate(prev) {
    if (prev.benchTheme !== this.props.benchTheme && this.props.benchTheme) this.setState({ theme: this.props.benchTheme });
    if (prev.benchState !== this.props.benchState && this.props.benchState) this.setState({ bench: this.props.benchState });
  }

  reduced() {
    return typeof window !== 'undefined' && window.matchMedia
      ? window.matchMedia('(prefers-reduced-motion: reduce)').matches : false;
  }

  deck() {
    return [
      { tag: 'DEFINITION', topic: 'GAS EXCHANGE', front: 'Define diffusion.', back: 'The net movement of particles from where they are more concentrated to where they are less concentrated.', mine: false },
      { tag: 'KEY FACT', topic: 'GAS EXCHANGE', front: 'Three things that make a gas exchange surface efficient.', back: 'A large surface area. Thin walls. A good blood supply.', mine: true },
      { tag: 'EQUATION', topic: 'PRESSURE', front: 'Pressure, force, area — which one sits on top?', back: 'Force sits on top: p = F / A.', mine: false, triangle: true },
      { tag: 'EQUATION', topic: 'CHEMICAL REACTIONS', front: 'Write the word equation for magnesium burning in oxygen.', back: '', mine: true, arrow: true, eqLeft: 'magnesium + oxygen', eqRight: 'magnesium oxide' },
      { tag: 'DEFINITION', topic: 'GAS EXCHANGE', front: 'Define ventilation.', back: 'Moving air into and out of the lungs.', mine: false },
      { tag: 'KEY FACT', topic: 'PRESSURE', front: 'A fixed amount of gas is squeezed into a smaller space. What happens to the pressure?', back: 'It goes up. The same particles hit a smaller area more often.', mine: false },
    ];
  }

  set(k, v) { this.setState({ [k]: v }); }

  renderVals() {
    const s = this.state;
    const deck = this.deck();
    const idx = ((s.idx % deck.length) + deck.length) % deck.length;
    const card = deck[idx];
    const pad = (n) => (n < 10 ? '0' + n : '' + n);

    const weeks = Array.from({ length: 12 }, (_, i) => {
      const n = i + 1;
      return {
        label: pad(n), sel: s.week === n ? '1' : '0', now: n === 4, later: n !== 4,
        title: 'Week ' + pad(n),
        pick: () => this.set('week', n),
      };
    });

    const tabLabels = [['ALL', 'ALL  2'], ['TODO', 'TO DO  0'], ['MARKED', 'MARKED  2']];
    const tabs = tabLabels.map(([id, label]) => ({
      label, on: s.filter === id ? '1' : '0', pick: () => this.set('filter', id),
    }));

    const rowData = [
      { week: 'W01', title: 'Breathing and gas exchange · Pressure · Chemical reactions', meta: '4 questions', score: '50%', feedback: 'Two of four. Your diffusion answer needs the words "high to low concentration" to earn the mark — the rest was solid.' },
      { week: 'W01', title: 'Particle model — recall and apply', meta: '2 marks', score: '50%', feedback: 'One of two. Say what happens to the spacing between particles, not just that they "move more".' },
    ];
    const rows = rowData.map((r, i) => ({
      ...r, open: s.openRow === i,
      toggle: () => this.set('openRow', s.openRow === i ? null : i),
    }));

    const lbchips = ['W01', 'W02', 'W03', 'W04', 'TERM'].map((label) => ({
      label, on: s.lbweek === label ? '1' : '0', pick: () => this.set('lbweek', label),
    }));

    const pips = deck.map((_, i) => ({ on: i <= idx ? '1' : '0' }));

    const themes = ['clay', 'chalk', 'moss', 'harbour', 'damson', 'graphite'];
    const pick = (t) => () => this.setState({ theme: t });

    const round = this.round();
    const q = round[Math.min(s.qi, 5)];
    const optState = (i) => {
      if (!s.checked) return s.picked === i ? 'picked' : 'idle';
      if (i === q.answer) return 'correct';
      return s.picked === i ? 'wrong' : 'idle';
    };
    const opts = q.options.map((label, i) => ({
      label, letter: 'ABCD'[i], st: optState(i),
      right: s.checked && i === q.answer,
      pick: () => { if (!s.checked) this.setState({ picked: i }); },
    }));
    const gotIt = s.checked && s.picked === q.answer;
    const advance = (scored) => {
      const last = s.qi >= 5;
      const streak = scored ? s.streak + 1 : 0;
      this.setState({
        answered: s.answered + 1,
        streak, best: Math.max(s.best, streak),
        roundScore: s.roundScore + (scored ? 1 : 0),
        picked: null, checked: false,
        qi: last ? 5 : s.qi + 1,
        roundDone: last,
        rounds: last ? s.rounds + 1 : s.rounds,
      });
    };

    return {
      theme: s.theme,
      recallOpen: s.recall,
      inRound: s.recall && !s.roundDone,
      roundDone: s.roundDone,
      roundLabel: 'ROUND ' + pad(s.roundNo),
      roundScore: s.roundScore + ' / 6',
      qPos: pad(Math.min(s.qi + 1, 6)) + ' / 06',
      qStep: String(s.qi),
      qpips: round.map((_, i) => ({ on: i <= s.qi ? '1' : '0' })),
      q, opts,
      checked: s.checked,
      canCheck: !s.checked,
      verdict: gotIt ? 'Correct.' : 'Not this time.',
      nextLabel: s.qi >= 5 ? 'Finish the round' : 'Next question',
      streakLabel: s.streak > 0 ? 'STREAK ' + pad(s.streak) : 'STREAK 00',
      answered: pad(s.answered),
      best: pad(s.best),
      rounds: pad(s.rounds),
      check: () => { if (s.picked !== null) this.setState({ checked: true }); },
      nextQ: () => advance(s.picked === q.answer),
      skipQ: () => advance(false),
      anotherRound: () => this.setState({ roundNo: s.roundNo + 1, qi: 0, picked: null, checked: false, roundScore: 0, roundDone: false, streak: 0 }),
      openRecall: () => this.setState({ recall: true, cards: false, account: false }),
      closeRecall: () => this.setState({ recall: false }),
      themeLabel: s.theme.toUpperCase(),
      benchOpen: s.bench === 'open',
      benchDone: s.bench === 'done',
      benchOpenOn: s.bench === 'open' ? '1' : '0',
      benchDoneOn: s.bench === 'done' ? '1' : '0',
      showBar: this.props.showStateBar !== false,
      weeks, tabs, rows, lbchips, pips,
      cardCount: pad(deck.length),
      stackPos: pad(idx + 1) + ' / ' + pad(deck.length),
      topFront: card.front,
      topMine: card.mine,
      card,
      flipOn: s.flipped ? '1' : '0',
      flipLabel: s.flipped ? 'Hide' : 'Reveal',
      flip: () => this.setState({ flipped: !s.flipped }),
      next: () => this.setState({ idx: idx + 1, flipped: false }),
      openCards: () => this.setState({ cards: true, account: false, flipped: false }),
      openAccount: () => this.setState({ account: true, cards: false }),
      closeAll: () => this.setState({ account: false, cards: false }),
      accountOpen: s.account,
      cardsOpen: s.cards,
      setOpen: () => this.set('bench', 'open'),
      setDone: () => this.set('bench', 'done'),
      cycleTheme: () => this.setState({ theme: themes[(themes.indexOf(s.theme) + 1) % themes.length] }),
      pickClay: pick('clay'), pickChalk: pick('chalk'), pickMoss: pick('moss'),
      pickHarbour: pick('harbour'), pickDamson: pick('damson'), pickGraphite: pick('graphite'),
      isClay: s.theme === 'clay' ? '1' : '0',
      isChalk: s.theme === 'chalk' ? '1' : '0',
      isMoss: s.theme === 'moss' ? '1' : '0',
      isHarbour: s.theme === 'harbour' ? '1' : '0',
      isDamson: s.theme === 'damson' ? '1' : '0',
      isGraphite: s.theme === 'graphite' ? '1' : '0',
    };
  }
}

