  TITLES = {
    'Science': ['Particle model — recall and apply', 'Energy stores and transfers', 'Separating mixtures', 'Acids and alkalis — the pH scale', 'Cells and the microscope', 'Forces and speed', 'Sound and hearing', 'The reactivity series', 'Photosynthesis — the basics', 'Light and reflection', 'Word equations', 'Digestion and enzymes'],
    'Combined Science': ['Rates of reaction — recall and apply', 'Bonding and structure', 'Electric circuits — current and voltage', 'Homeostasis — control systems', 'Cell transport and osmosis', 'Energy resources and efficiency', 'The periodic table — trends', 'Inheritance and genetics', 'Waves — the EM spectrum', 'Ecosystems and cycles', 'Quantitative chemistry — moles', 'Motion graphs'],
    'Physics': ['Forces and motion — resultants', 'Electric circuits — current and voltage', 'Waves — reflection and refraction', 'Energy transfers and efficiency', 'Radioactivity — half-life', 'Momentum and collisions', 'Magnetism and the motor effect', 'Pressure in fluids', 'Gas laws and particle theory', 'Static electricity', 'Specific heat capacity', 'Terminal velocity']
  };

  STEMS = [
    { id: 'Q1', text: 'Recall — key definition' },
    { id: 'Q2', text: 'Recall — units and symbols' },
    { id: 'Q3', text: 'Identify — read the diagram' },
    { id: 'Q4', text: 'Apply — one-step calculation' },
    { id: 'Q5', text: 'Apply — two-step calculation' },
    { id: 'Q6', text: 'Explain — why it happens' },
    { id: 'Q7', text: 'Compare — two cases' },
    { id: 'Q8', text: 'Evaluate — apply to a new context' }
  ];

  TOPICS = [
    { id: 't1', name: 'Particle model of matter', unit: 'KS3 · Chemistry · Unit 4', tag: 'Set 3 weeks ago' },
    { id: 't2', name: 'Energy stores and transfers', unit: 'KS3 · Physics · Unit 2', tag: 'Just marked' },
    { id: 't3', name: 'Cells and organisation', unit: 'KS3 · Biology · Unit 1', tag: 'Not set yet' },
    { id: 't4', name: 'Acids, alkalis and neutralisation', unit: 'KS3 · Chemistry · Unit 5', tag: 'Set 6 weeks ago' },
    { id: 't5', name: 'Forces and motion', unit: 'KS3 · Physics · Unit 3', tag: 'Not set yet' }
  ];

  TEMPLATES = [
    { id: 1, label: 'Top of the class this week' },
    { id: 2, label: 'Brilliant improvement' },
    { id: 3, label: 'Every assignment on time' },
    { id: 4, label: 'Smashed a tough topic' },
    { id: 5, label: 'Bounced back strong' },
    { id: 6, label: 'Helped a classmate' }
  ];

  POOL_CLASSES = ['7hsc5', '8rsc1', '9hsc5', '10hph1', '10hsc2'];

  seed(str) {
    let h = 2166136261;
    const s = String(str);
    for (let i = 0; i < s.length; i++) { h ^= s.charCodeAt(i); h = (h * 16777619) >>> 0; }
    return h >>> 0;
  }
  rnd(key, lo, hi) { return lo + (this.seed(key) % (hi - lo + 1)); }
  initials(name) {
    const p = String(name).trim().split(/\s+/);
    return ((p[0] || '')[0] || '') + ((p[1] || '')[0] || '');
  }
  hueFor(name) { return this.HUE[this.seed(name) % this.HUE.length]; }
  dotsFor(sub) {
    if (sub === 'Physics') return [{ w: 8, c: 'var(--ks3-physics)' }];
    if (sub === 'Chemistry') return [{ w: 8, c: 'var(--ks3-chemistry)' }];
    if (sub === 'Biology') return [{ w: 8, c: 'var(--ks3-biology)' }];
    return [{ w: 3, c: 'var(--ks3-physics)' }, { w: 3, c: 'var(--ks3-chemistry)' }, { w: 3, c: 'var(--ks3-biology)' }];
  }
  ping(msg) {
    this.setState({ toast: msg });
    clearTimeout(this._t);
    this._t = setTimeout(() => this.setState({ toast: '' }), 2800);
  }
  klassById(id) { return this.CLASSES.filter(c => c.id === id)[0]; }
  klass() { return this.klassById(this.state.classId) || this.CLASSES[3]; }

  /* ── ONE seeded score matrix per class (student x paper, marks out of 8).
     Every average on every screen is derived from this: a student's avg is
     the mean of their row, a paper's mean is the mean of its column, the
     class mean is the mean of the marked columns, the digest mean is the
     mean of the class means. No second source of truth. ── */
  matrixFor(k) {
    this._mx = this._mx || {};
    if (this._mx[k.id]) return this._mx[k.id];
    const live = k.state === 'live';
    const cols = live ? this.weeks().length : 0;
    const rows = [];
    for (let i = 0; i < k.n; i++) {
      const sid = k.id + '-' + i;
      const inWeek = live && i < k.week[0];
      const scores = [];
      const late = [];
      for (let p = 0; p < cols; p++) {
        let sc = null, lt = false;
        if (p === 0) {
          if (inWeek) { sc = this.rnd(sid + ':c0', 2, 8); }
        } else if (this.rnd(sid + ':c' + p + 'm', 0, 11) !== 0) {
          sc = this.rnd(sid + ':c' + p, 2, 8);
          lt = this.rnd(sid + ':c' + p + 'l', 0, 5) === 0;
        }
        scores.push(sc);
        late.push(lt);
      }
      rows.push({ sid, scores, late, inWeek });
    }
    const colMean = [], colSub = [], colOnTime = [];
    for (let p = 0; p < cols; p++) {
      const vals = rows.map(r => r.scores[p]).filter(v => v != null);
      colSub.push(vals.length);
      colMean.push(vals.length ? Math.round((vals.reduce((a, v) => a + v, 0) / vals.length / 8) * 100) : null);
      colOnTime.push(rows.filter(r => r.scores[p] != null && !r.late[p]).length);
    }
    const studentAvg = {};
    rows.forEach(r => {
      const vals = r.scores.slice(1).filter(v => v != null).map(v => Math.round((v / 8) * 100));
      studentAvg[r.sid] = vals.length ? Math.round(vals.reduce((a, v) => a + v, 0) / vals.length) : null;
    });
    const marked = colMean.slice(1).filter(v => v != null);
    const markedSub = colSub.slice(1).reduce((a, v) => a + v, 0);
    const markedOnTime = colOnTime.slice(1).reduce((a, v) => a + v, 0);
    const out = {
      rows, colMean, colSub, colOnTime, studentAvg,
      markedSub, markedOnTime,
      markedPct: markedSub ? Math.round((markedOnTime / markedSub) * 100) : null,
      classMean: marked.length ? Math.round(marked.reduce((a, v) => a + v, 0) / marked.length) : null,
      byId: {}
    };
    rows.forEach(r => { out.byId[r.sid] = r; });
    this._mx[k.id] = out;
    return out;
  }

  rosterFor(k) {
    this._rc = this._rc || {};
    if (this._rc[k.id]) return this._rc[k.id];
    const off = this.seed(k.id) % this.NAMES.length;
    const live = k.state === 'live';
    const mx = this.matrixFor(k);
    const rows = [];
    for (let i = 0; i < k.n; i++) {
      const sid = k.id + '-' + i;
      const row = mx.byId[sid];
      const avg = live ? mx.studentAvg[sid] : null;
      const inWeek = !!(row && row.inWeek);
      const missing = !!(row && row.scores.slice(1).indexOf(null) > -1);
      const li = this.rnd(sid + 'l', inWeek ? 0 : 6, inWeek ? 5 : 10);
      rows.push({
        id: sid,
        name: this.NAMES[(off + i) % this.NAMES.length],
        avg,
        inWeek,
        last: this.LASTS[li],
        hours: this.HOURS[li],
        flag: live && !inWeek && (missing || (avg != null && avg < 50))
      });
    }
    this._rc[k.id] = rows;
    return rows;
  }

  papersFor(k) {
    if (k.state !== 'live') return [];
    this._pc = this._pc || {};
    if (this._pc[k.id]) return this._pc[k.id];
    const t = this.TITLES[k.subject] || this.TITLES['Science'];
    const wks = this.weeks();
    const mx = this.matrixFor(k);
    const out = wks.map((w, i) => ({
      id: k.id + ':p' + i,
      idx: i,
      title: t[i % t.length],
      due: i === 0 ? 'Due ' + w.due : w.due,
      set: w.set,
      range: w.range,
      dueShort: w.dueShort,
      lateShort: w.lateShort,
      sub: mx.colSub[i] + '/' + k.n,
      mean: mx.colMean[i] == null ? '—' : mx.colMean[i] + '%',
      when: i === 0 ? 'upcoming' : 'marked'
    }));
    this._pc[k.id] = out;
    return out;
  }

  /* The term, newest week first: index 0 is the open week, 11 is as far back
     as the class history goes. Every week owns one assignment column. */
  weeks() {
    if (this._weeks) return this._weeks;
    const M = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec'];
    const lab = (dt) => dt.getDate() + ' ' + M[dt.getMonth()];
    const first = new Date(2026, 7, 26);
    const out = [];
    for (let i = 0; i < 12; i++) {
      const due = new Date(first); due.setDate(first.getDate() - i * 7);
      /* Work is set on a Wednesday and due the next: a week's range is the
         teaching week it was set in, not the week its deadline falls in. */
      const mon = new Date(due); mon.setDate(due.getDate() - 9);
      const fri = new Date(due); fri.setDate(due.getDate() - 5);
      const setOn = new Date(due); setOn.setDate(due.getDate() - 7);
      out.push({
        range: mon.getMonth() === fri.getMonth() ? mon.getDate() + '–' + lab(fri) : lab(mon) + '–' + lab(fri),
        due: 'Wed ' + lab(due),
        set: 'Wed ' + lab(setOn),
        dueShort: lab(due),
        lateShort: lab(fri)
      });
    }
    this._weeks = out;
    return out;
  }
  rail() { return document.querySelector('[data-rail="weeks"]'); }
  /* The strip runs oldest to newest, so it opens parked on this week. */
  snapWeekRail() {
    const snap = () => {
      const el = this.rail();
      if (!el) return;
      if (!this.state.weekIdx) { el.scrollLeft = el.scrollWidth; return; }
      const chip = el.querySelector('[data-week="' + this.state.weekIdx + '"]');
      if (chip) el.scrollLeft = Math.max(0, chip.offsetLeft - (el.clientWidth - chip.offsetWidth) / 2);
    };
    requestAnimationFrame(snap);
    setTimeout(snap, 90);
  }
  openClass(patch) { this.setState({ screen: 'class', weekIdx: 0, ...patch }, () => this.snapWeekRail()); }
  pickWeek(i) {
    this.setState({ weekIdx: i }, () => {
      const el = this.rail();
      if (!el) return;
      const chip = el.querySelector('[data-week="' + i + '"]');
      if (!chip) return;
      const left = chip.offsetLeft, right = left + chip.offsetWidth;
      if (left < el.scrollLeft + 8) el.scrollTo({ left: Math.max(0, left - 14), behavior: 'smooth' });
      else if (right > el.scrollLeft + el.clientWidth - 8) el.scrollTo({ left: right - el.clientWidth + 14, behavior: 'smooth' });
    });
  }
  weekIdxFor(k) {
    const n = this.papersFor(k).length;
    if (!n) return 0;
    return Math.min(Math.max(0, this.state.weekIdx || 0), n - 1);
  }

  /* Per-paper question grid, also derived from the matrix: a student's marks
     decide how many cells are correct, question difficulty decides which. So
     the row marks, the question percentages and the paper mean all agree. */
  gridFor(k, pIdx) {
    this._gc = this._gc || {};
    const key = k.id + ':' + pIdx;
    if (this._gc[key]) return this._gc[key];
    const mx = this.matrixFor(k);
    const roster = this.rosterFor(k);
    const diff = this.STEMS.map(q => this.rnd(k.id + ':p' + pIdx + ':' + q.id, 20, 95));
    let submitted = 0;
    const correctCount = this.STEMS.map(() => 0);
    const rows = roster.map(r => {
      const row = mx.byId[r.id];
      const marks = row ? row.scores[pIdx] : null;
      const base = { name: r.name, initials: this.initials(r.name), hue: this.hueFor(r.name), id: r.id };
      if (marks == null) {
        return { ...base, raw: this.STEMS.map(() => 2), score: '—' };
      }
      submitted++;
      const order = this.STEMS
        .map((q, qi) => ({ qi, w: diff[qi] + this.rnd(r.id + q.id, -18, 18) }))
        .sort((a, b) => b.w - a.w)
        .slice(0, marks)
        .map(o => o.qi);
      const hit = {};
      order.forEach(qi => { hit[qi] = true; });
      const raw = this.STEMS.map((q, qi) => {
        if (hit[qi]) { correctCount[qi]++; return 1; }
        return this.rnd(r.id + q.id + 'x', 0, 30) === 0 ? 2 : 0;
      });
      return { ...base, raw, score: marks + '/8' };
    });
    const qpct = correctCount.map(c => (submitted ? Math.round((c / submitted) * 100) : 0));
    const out = { rows, qpct, submitted };
    this._gc[key] = out;
    return out;
  }

  BANDS = [
    { label: '0–39', lo: 0, hi: 39 },
    { label: '40–54', lo: 40, hi: 54 },
    { label: '55–69', lo: 55, hi: 69 },
    { label: '70–84', lo: 70, hi: 84 },
    { label: '85–100', lo: 85, hi: 100 }
  ];
  HOURS = [0.2, 0.5, 0.8, 1, 2, 3, 20, 48, 96, 144, 216];
  CHART_KINDS = [
    { id: 'submissions', label: 'Submissions' },
    { id: 'means', label: 'Class means' },
    { id: 'spread', label: 'Score spread' },
    { id: 'ontime', label: 'On time' },
    { id: 'questions', label: 'Question difficulty' },
    { id: 'engagement', label: 'Engagement' }
  ];

  colsFrom(items, cap) {
    const max = cap || Math.max.apply(null, items.map(i => i.raw).concat([1]));
    return items.map(i => ({
      label: i.label,
      value: i.value,
      note: i.note || '',
      pct: Math.round((i.raw / (max || 1)) * 100),
      fill: i.flag ? 'var(--st-accent)' : (i.fill || 'var(--st-hatch-b)'),
      labelFg: i.flag ? 'var(--st-accent-text)' : 'var(--st-caption)'
    }));
  }
  bucketsOf(rows) {
    return {
      today: rows.filter(r => r.hours < 24).length,
      week: rows.filter(r => r.hours >= 24 && r.hours < 168).length,
      stale: rows.filter(r => r.hours >= 168).length
    };
  }

  /* Every chart reads the same class matrix the tables read, so a chart can
     never disagree with the screen a teacher clicked through from. */
  chartFor(kind, scope) {
    const all = scope === 'all';
    const live = this.CLASSES.filter(c => c.state === 'live');
    const k = all ? null : (this.klassById(scope) || this.CLASSES[3]);
    const mx = (c) => this.matrixFor(c);
    const tile = (label, value, sub) => ({ label, value: String(value), sub: sub || '' });
    const base = { type: 'bars', title: '', note: '', tiles: [], rows: [], cols: [], stacks: [], legend: [] };

    if (kind === 'means') {
      if (all) {
        const raw = live.map(c => ({ code: c.code, ks: c.ks, mean: mx(c).classMean || 0 }));
        const cohort = Math.round(raw.reduce((a, r) => a + r.mean, 0) / (raw.length || 1));
        const below = raw.filter(r => r.mean < cohort).length;
        const sorted = raw.slice().sort((a, b) => b.mean - a.mean);
        return { ...base, title: 'Class means, marked work', tiles: [
          tile('Cohort mean', cohort + '%', 'Mean of ' + raw.length + ' class means'),
          tile('Highest', sorted[0].code + ' · ' + sorted[0].mean + '%', ''),
          tile('Lowest', sorted[sorted.length - 1].code + ' · ' + sorted[sorted.length - 1].mean + '%', '')
        ], note: below + ' of ' + raw.length + ' classes sit below the ' + cohort + '% cohort mean',
          rows: sorted.map(r => ({ label: r.code, sub: r.ks + (r.mean < cohort ? ' · below cohort' : ''), value: r.mean + '%', pct: r.mean, fill: r.mean < cohort ? 'var(--st-accent)' : 'var(--st-hatch-b)', })) };
      }
      const m = mx(k);
      const ps = this.papersFor(k).slice().sort((a, b) => b.idx - a.idx).filter(p => p.when === 'marked' && m.colMean[p.idx] != null);
      const means = ps.map(p => m.colMean[p.idx]);
      const best = ps[means.indexOf(Math.max.apply(null, means))];
      const worst = ps[means.indexOf(Math.min.apply(null, means))];
      return { ...base, type: 'cols', title: k.code + ' — mean by assignment',
        cols: this.colsFrom(ps.map(p => ({ label: p.due.replace('Due ', ''), value: m.colMean[p.idx] + '%', raw: m.colMean[p.idx], flag: p.idx === worst.idx })), 100),
        tiles: [tile('Class mean', (m.classMean == null ? '—' : m.classMean + '%'), 'Across ' + ps.length + ' marked assignments'),
          tile('Strongest', Math.max.apply(null, means) + '%', best.title),
          tile('Weakest', Math.min.apply(null, means) + '%', worst.title),
          tile('Open work', 'Excluded', 'Not marked yet')],
        note: 'Weakest set: ' + worst.title + ' at ' + m.colMean[worst.idx] + '%' };
    }

    if (kind === 'spread') {
      const src = all ? live : [k];
      const avgs = src.reduce((a, c) => a.concat(this.rosterFor(c).map(r => r.avg).filter(v => v != null)), []);
      const bands = this.BANDS.map(b => ({ label: b.label, n: avgs.filter(v => v >= b.lo && v <= b.hi).length, lo: b.lo }));
      const low = bands.filter(b => b.lo < 55).reduce((a, b) => a + b.n, 0);
      const high = bands.filter(b => b.lo >= 70).reduce((a, b) => a + b.n, 0);
      const ranked = bands.slice().sort((a, b) => b.n - a.n);
      const modeTie = ranked.length > 1 && ranked[1].n === ranked[0].n;
      return { ...base, type: 'cols', title: (all ? 'Score spread, all classes' : k.code + ' — score spread'),
        cols: this.colsFrom(bands.map(b => ({ label: b.label, value: String(b.n), raw: b.n, flag: b.lo < 55 }))),
        tiles: [tile('Students', avgs.length, 'With marked work'), tile('Below 55%', low, 'Bottom two bands'), tile('70% or above', high, 'Top two bands')],
        note: modeTie
          ? low + ' of ' + avgs.length + ' students sit below 55%, ' + high + ' at 70% or above'
          : 'Most students sit in the ' + ranked[0].label + ' band (' + ranked[0].n + ' of ' + avgs.length + ')' };
    }

    if (kind === 'ontime') {
      const src = all
        ? live.map(c => ({ label: c.code, sub: c.ks, on: mx(c).markedOnTime, tot: mx(c).markedSub }))
        : this.papersFor(k).filter(p => p.when === 'marked').map(p => ({ label: p.title, sub: 'Due ' + p.due, on: mx(k).colOnTime[p.idx], tot: mx(k).colSub[p.idx] }));
      const on = src.reduce((a, x) => a + x.on, 0);
      const tot = src.reduce((a, x) => a + x.tot, 0);
      const worst = src.slice().sort((a, b) => (a.tot ? a.on / a.tot : 1) - (b.tot ? b.on / b.tot : 1))[0];
      return { ...base, type: 'stack', title: (all ? 'On time vs late, marked work' : k.code + ' — on time by assignment'),
        stacks: src.map(x => {
          const pct = x.tot ? Math.round((x.on / x.tot) * 100) : 0;
          return { label: x.label, sub: x.sub, right: pct + '% · ' + (x.tot - x.on) + ' late',
            segs: [{ pct, fill: 'var(--ks3-ok)' }, { pct: 100 - pct, fill: 'var(--st-accent)' }] };
        }),
        legend: [{ label: 'On time', fill: 'var(--ks3-ok)' }, { label: 'Late', fill: 'var(--st-accent)' }],
        tiles: [tile('On time', (tot ? Math.round((on / tot) * 100) : 0) + '%', 'Of ' + tot + ' marked submissions'), tile('Late', tot - on, 'Still marked'), tile('Open work', 'Excluded', 'Not due yet')],
        note: worst ? 'Weakest: ' + worst.label + ' at ' + (worst.tot ? Math.round((worst.on / worst.tot) * 100) : 0) + '% on time' : '' };
    }

    if (kind === 'questions') {
      if (all) {
        const rows = live.map(c => {
          const g = this.gridFor(c, 1);
          const min = Math.min.apply(null, g.qpct);
          const qi = g.qpct.indexOf(min);
          return { label: c.code, sub: this.STEMS[qi].id + ' · ' + this.STEMS[qi].text, value: min + '%', pct: min, fill: min < 50 ? 'var(--st-accent)' : 'var(--st-hatch-b)', qi };
        });
        const tally = {};
        rows.forEach(r => { tally[r.qi] = (tally[r.qi] || 0) + 1; });
        const keys = Object.keys(tally).sort((a, b) => tally[b] - tally[a]);
        const uniqueTop = keys.length === 1 || tally[keys[0]] > tally[keys[1]];
        const worst = rows.slice().sort((a, b) => a.pct - b.pct)[0];
        const under50 = rows.filter(r => r.pct < 50).length;
        return { ...base, title: 'Weakest question per class, last marked set', rows,
          tiles: [tile('Classes', rows.length, 'With marked work'), tile('Lowest', worst.label + ' · ' + worst.value, worst.sub),
            uniqueTop
              ? tile('Most common', this.STEMS[keys[0]].id, this.STEMS[keys[0]].text)
              : tile('Weak points', keys.length + ' questions', 'No single common gap')],
          note: uniqueTop
            ? this.STEMS[keys[0]].text + ' is the weakest question in ' + tally[keys[0]] + ' of ' + rows.length + ' classes'
            : 'No single common gap — ' + keys.length + ' different questions come last, and ' + under50 + ' classes fall below 50% on theirs' };
      }
      const g = this.gridFor(k, 1);
      const p = this.papersFor(k)[1];
      const min = Math.min.apply(null, g.qpct);
      const max = Math.max.apply(null, g.qpct);
      const qi = g.qpct.indexOf(min);
      return { ...base, type: 'cols', title: k.code + ' — ' + p.title,
        cols: this.colsFrom(this.STEMS.map((q, i) => ({ label: q.id, value: g.qpct[i] + '%', raw: g.qpct[i], flag: g.qpct[i] === min })), 100),
        tiles: [tile('Paper mean', mx(k).colMean[1] + '%', g.submitted + ' of ' + k.n + ' submitted'),
          tile('Lowest', this.STEMS[qi].id + ' · ' + min + '%', this.STEMS[qi].text), tile('Highest', max + '%', 'Best answered question')],
        note: 'Reteach ' + this.STEMS[qi].text.toLowerCase() + ' — ' + min + '% of the class got it' };
    }

    if (kind === 'engagement') {
      if (all) {
        const totals = { today: 0, week: 0, stale: 0 };
        const stacks = live.map(c => {
          const b = this.bucketsOf(this.rosterFor(c));
          totals.today += b.today; totals.week += b.week; totals.stale += b.stale;
          const t = c.n || 1;
          return { label: c.code, sub: c.ks, right: b.today + ' today · ' + b.stale + ' cold',
            segs: [{ pct: Math.round((b.today / t) * 100), fill: 'var(--ks3-ok)' }, { pct: Math.round((b.week / t) * 100), fill: 'var(--st-hatch-b)' }, { pct: Math.round((b.stale / t) * 100), fill: 'var(--st-rule-strong)' }] };
        });
        return { ...base, type: 'stack', title: 'Last seen, by class', stacks,
          legend: [{ label: 'Today', fill: 'var(--ks3-ok)' }, { label: 'This week', fill: 'var(--st-hatch-b)' }, { label: '2+ weeks', fill: 'var(--st-rule-strong)' }],
          tiles: [tile('Active today', totals.today, 'Across ' + live.length + ' classes'), tile('This week', totals.week, ''), tile('2+ weeks', totals.stale, 'Worth chasing')],
          note: totals.stale + ' students have not opened anything for two weeks or more' };
      }
      const rows = this.rosterFor(k);
      const b = this.bucketsOf(rows);
      const cold = rows.filter(r => r.hours >= 168).map(r => r.name);
      return { ...base, type: 'cols', title: k.code + ' — last seen',
        cols: this.colsFrom([{ label: 'Today', value: String(b.today), raw: b.today }, { label: 'This week', value: String(b.week), raw: b.week }, { label: '2+ weeks', value: String(b.stale), raw: b.stale, flag: b.stale > 0 }]),
        tiles: [tile('Students', k.n, 'On the roster'), tile('Active today', b.today, ''), tile('2+ weeks', b.stale, cold.length ? 'Worth chasing' : 'None')],
        note: cold.length ? 'Not seen for two weeks: ' + cold.slice(0, 3).join(', ') + (cold.length > 3 ? ' and ' + (cold.length - 3) + ' more' : '') : 'Everyone has opened something this week' };
    }

    if (all) {
      const rows = live.map(c => {
        const m = mx(c);
        const pct = c.n ? Math.round((m.colSub[0] / c.n) * 100) : 0;
        return { label: c.code, sub: c.ks, value: m.colSub[0] + '/' + c.n, pct, fill: pct < 60 ? 'var(--st-accent)' : 'var(--st-hatch-b)' };
      });
      const subs = live.reduce((a, c) => a + mx(c).colSub[0], 0);
      const seats = live.reduce((a, c) => a + c.n, 0);
      const done = live.filter(c => mx(c).colSub[0] === c.n).length;
      const low = rows.slice().sort((a, b) => a.pct - b.pct)[0];
      return { ...base, title: 'Submissions this week', rows,
        tiles: [tile('Submitted', subs + '/' + seats, 'Across ' + live.length + ' classes'), tile('Outstanding', seats - subs, 'Students yet to submit'), tile('Everyone in', done + '/' + live.length, 'Classes complete')],
        note: low ? 'Lowest return: ' + low.label + ' at ' + low.pct + '% (' + low.value + ')' : '' };
    }
    const m = mx(k);
    const rows = this.papersFor(k).map(p => {
      const pct = k.n ? Math.round((m.colSub[p.idx] / k.n) * 100) : 0;
      return { label: p.title, sub: (p.when === 'upcoming' ? 'Open · due ' + p.due.replace('Due ', '') : 'Marked · due ' + p.due), value: m.colSub[p.idx] + '/' + k.n, pct, fill: pct < 60 ? 'var(--st-accent)' : 'var(--st-hatch-b)' };
    });
    const lowP = rows.slice().sort((a, b) => a.pct - b.pct)[0];
    return { ...base, title: k.code + ' — submissions by assignment', rows,
      tiles: [tile('This week', m.colSub[0] + '/' + k.n, 'Open assignment'), tile('Outstanding', k.n - m.colSub[0], 'Students yet to submit'), tile('Assignments', rows.length, 'Set this term')],
      note: lowP ? 'Weakest return: ' + lowP.label + ' at ' + lowP.pct + '%' : '' };
  }

  paper() {
    const list = this.papersFor(this.klass());
    return list.filter(p => p.id === this.state.paperId)[0] || list[1] || list[0] || null;
  }
  student() {
    const rows = this.rosterFor(this.klass());
    return rows.filter(r => r.id === this.state.studentId)[0] || rows[0] || null;
  }
  meanOf(k) { return this.matrixFor(k).classMean; }
  cellStyle(v) {
    if (v === 1) return { w: 9, h: 9, r: '50%', bg: 'var(--ks3-ok)', bd: 'none' };
    if (v === 0) return { w: 9, h: 9, r: '50%', bg: 'transparent', bd: '1.5px solid var(--st-rule-strong)' };
    return { w: 9, h: 2, r: '1px', bg: 'var(--st-rule-strong)', bd: 'none' };
  }

  renderVals() {
    const s = this.state;
    const meter = (this.props.cardMeter ?? 'bar') === 'bar';
    const hideEmpty = this.props.hideEmptyClasses ?? false;
    const compact = (this.props.density ?? 'comfortable') === 'compact';
    const teacher = this.props.teacherName ?? 'Ayomide';

    const k = this.klass();
    const kRoster = this.rosterFor(k);
    const kPapers = this.papersFor(k);
    const kMx = this.matrixFor(k);
    const st = this.student();
    const pp = this.paper();
    const totalStudents = this.CLASSES.reduce((a, c) => a + c.n, 0);
    const totalSubs = this.CLASSES.reduce((a, c) => a + c.week[0], 0);
    const liveClasses = this.CLASSES.filter(c => c.state === 'live');

    const pill = (on) => on
      ? { bg: 'var(--st-paper)', fg: 'var(--st-ink)', bc: 'var(--st-btn-border)' }
      : { bg: 'transparent', fg: 'var(--st-caption)', bc: 'transparent' };

    let list = this.CLASSES.filter(c => s.ks === 'All' || c.ks === s.ks);
    if (hideEmpty) list = list.filter(c => c.n > 0);
    if (s.sort === 'activity') {
      const rank = { live: 1, nowork: 0, empty: 0 };
      list = list.slice().sort((a, b) => {
        const ga = a.state === 'live' ? (a.week[1] - a.week[0]) : 999;
        const gb = b.state === 'live' ? (b.week[1] - b.week[0]) : 999;
        return gb - ga;
      });
    }

    const cards = list.map(c => ({
      code: c.code,
      subject: c.subject,
      dots: this.dotsFor(c.subject),
      meta: 'Year ' + c.year + ' · ' + c.ks + ' · 2026–27',
      live: c.state === 'live',
      noWork: c.state === 'nowork',
      empty: c.state === 'empty',
      weekLabel: c.week[0] + '/' + c.week[1],
      weekSub: c.week[0] === c.week[1]
        ? 'Everyone in · ' + c.n + ' students'
        : (c.week[1] - c.week[0]) + ' still to submit · ' + c.n + ' students',
      pct: c.week[1] ? Math.round((c.week[0] / c.week[1]) * 100) : 0,
      emptyLine: c.state === 'empty' ? 'No students yet' : c.n + ' students · no work set',
      activity: c.state === 'empty' ? c.last : 'Last activity ' + c.last,
      open: () => c.n > 0
        ? this.openClass({ classId: c.id })
        : this.setState({ screen: 'import', importStep: 1 }),
      act: (e) => {
        e.stopPropagation();
        if (c.state === 'empty') this.setState({ screen: 'import', importStep: 1 });
        else this.setState({ modal: 'setwork', swStep: 1, swClasses: [c.id] });
      }
    }));

    /* Which week the class screen is scoped to: 0 is the open assignment,
       1+ are the weeks behind it. Every figure below reads the same matrix
       column, so a past week can't disagree with the term view. */
    const wi = this.weekIdxFor(k);
    const wPast = wi > 0;
    const weekTabs = kPapers.slice().reverse().map((p, n) => {
      const i = p.idx;
      const on = i === wi;
      return {
        idx: String(i),
        range: p.range,
        on,
        now: i === 0,
        pick: () => this.pickWeek(i),
        bg: on ? 'var(--st-num-well)' : 'transparent',
        ring: on ? 'inset 0 0 0 1.5px var(--st-accent)' : 'none',
        divider: n === 0 || on ? 'transparent' : 'var(--st-rule-soft)',
        dateColor: on ? 'var(--st-ink)' : 'var(--st-muted)'
      };
    });
    const backOff = wi >= kPapers.length - 1;
    const fwdOff = wi <= 0;
    const wPaper = kPapers[wi];
    const wMean = kMx.colMean[wi];
    const wLate = Math.max(0, kMx.colSub[wi] - kMx.colOnTime[wi]);
    const kTermMean = this.meanOf(k);
    const wGap = wMean != null && kTermMean != null ? wMean - kTermMean : null;
    const weekNote = !kPapers.length ? ''
      : (wPast
        ? 'Week of ' + wPaper.range + ' · ' + wPaper.title + ' · marked, due ' + wPaper.due
        : 'Week of ' + wPaper.range + ' · ' + wPaper.title + ' · open, due ' + wPaper.due.replace(/^Due /, ''));

    const roster = kRoster.map(r => {
      const mrow = kMx.byId[r.id];
      const sc = mrow ? mrow.scores[wi] : null;
      const late = !!(mrow && mrow.late[wi]);
      const scPct = sc == null ? 0 : Math.round((sc / 8) * 100);
      return {
        name: r.name,
        initials: this.initials(r.name),
        hue: this.hueFor(r.name),
        hasWork: kPapers.length > 0,
        pct: wPast ? scPct : (r.inWeek ? 100 : 0),
        weekLabel: kPapers.length === 0 ? 'No work set'
          : (wPast
            ? (sc == null ? 'Not submitted' : scPct + '% · ' + (late ? 'late' : 'on time'))
            : (r.inWeek ? '1/1 on time' : '0/1 in')),
        avg: r.avg == null ? '—' : r.avg + '%',
        last: r.last,
        flag: r.flag,
        open: () => this.setState({ screen: 'student', studentId: r.id })
      };
    });

    const paperRow = (p) => ({
      title: p.title, due: p.due, sub: p.sub, mean: p.mean, sel: p.idx === wi,
      open: () => this.setState({ screen: 'marking', paperId: p.id })
    });

    const flagged = kRoster.filter(r => r.flag).length;
    const kMean = this.meanOf(k);
    const upcomingPaper = kPapers.filter(p => p.when === 'upcoming')[0];

    const pGrid = pp ? this.gridFor(k, pp.idx) : null;
    const questions = pGrid ? this.STEMS.map((q, qi) => ({ id: q.id, text: q.text, pct: pGrid.qpct[qi] })) : [];
    const worst = questions.length ? questions.reduce((a, q) => (q.pct < a.pct ? q : a), questions[0]) : null;

    const grid = pGrid ? pGrid.rows.slice(0, 10).map(r => ({
      name: r.name, initials: r.initials, hue: r.hue,
      cells: r.raw.map(v => this.cellStyle(v)),
      score: r.score,
      open: () => this.setState({ screen: 'student', studentId: r.id })
    })) : [];

    const digestRows = this.CLASSES.map(c => {
      const live = c.state === 'live';
      const m = live ? this.meanOf(c) : null;
      const fl = live ? this.rosterFor(c).filter(r => r.flag).length : 0;
      return {
        code: c.code, ks: c.ks,
        sub: live ? c.week[0] + '/' + c.week[1] : '—',
        mean: m == null ? '—' : m + '%',
        ontime: live && this.matrixFor(c).markedPct != null ? this.matrixFor(c).markedPct + '%' : '—',
        needs: c.state === 'empty'
          ? 'Roster not imported'
          : (c.state === 'nowork' ? 'No work set for two weeks' : (fl ? (fl === 1 ? '1 student to chase' : fl + ' students to chase') : 'Nothing outstanding')),
        open: () => c.n > 0 ? this.openClass({ classId: c.id, digestScope: 'all' }) : this.ping('No students in ' + c.code + ' yet')
      };
    });

    const chartKind = s.chartKind || 'submissions';
    const chartScope = s.chartScope || 'all';
    const chart = this.chartFor(chartKind, chartScope);

    const isClassReport = s.digestScope === 'class';
    const kFlagged = kRoster.filter(r => r.flag).length;
    const classReportRows = kPapers.map(p => {
      const missing = k.n - kMx.colSub[p.idx];
      return {
        code: p.title,
        ks: p.when === 'upcoming' ? 'Open' : 'Marked',
        sub: p.sub,
        mean: p.mean,
        ontime: p.when === 'upcoming' ? '—' : String(kMx.colOnTime[p.idx]),
        needs: missing === 0
          ? 'Everyone submitted'
          : (p.when === 'upcoming'
            ? (missing === 1 ? '1 still to submit' : missing + ' still to submit')
            : (missing === 1 ? '1 never submitted' : missing + ' never submitted')),
        open: () => this.setState({ screen: 'marking', paperId: p.id })
      };
    });

    const pool = [];
    this.POOL_CLASSES.forEach(id => {
      const kk = this.klassById(id);
      this.rosterFor(kk).slice(0, 3).forEach(r => {
        pool.push({ name: r.name, klass: kk.code, classId: kk.id, id: r.id, avg: r.avg == null ? '—' : r.avg + '%' });
      });
    });
    const q = String(s.search || '').toLowerCase();
    const results = pool.filter(p => !q || p.name.toLowerCase().indexOf(q) > -1).slice(0, 12).map(p => ({
      name: p.name, klass: p.klass, avg: p.avg,
      initials: this.initials(p.name), hue: this.hueFor(p.name),
      open: () => this.setState({ screen: 'student', classId: p.classId, studentId: p.id, modal: null })
    }));

    const swSel = s.swClasses;
    const swStudents = this.CLASSES.filter(c => swSel.indexOf(c.id) > -1).reduce((a, c) => a + c.n, 0);
    const topic = this.TOPICS.filter(t => t.id === s.swTopic)[0] || this.TOPICS[0];

    const stRow = st ? kMx.byId[st.id] : null;
    const stHistory = st && kPapers.length ? kPapers.map((p, i) => {
      const open = i === 0;
      const sc = stRow ? stRow.scores[i] : null;
      const late = !open && sc != null && stRow.late[i];
      const pct = sc == null ? null : Math.round((sc / 8) * 100);
      const tone = open ? 'neutral' : (sc == null || late ? 'warn' : 'ok');
      return {
        marked: !open && sc != null,
        missing: !open && sc == null,
        late: late,
        pct: open ? null : pct,
        title: p.title,
        due: p.due.replace('Due ', ''),
        submitted: open ? (sc != null ? st.last : 'Not yet') : (sc == null ? '—' : (late ? p.lateShort : p.dueShort)),
        score: open || sc == null ? '—' : sc + '/8 · ' + pct + '%',
        status: open ? (sc != null ? 'In progress' : 'Nothing in') : (sc == null ? 'Nothing in' : (late ? 'Late' : 'On time')),
        stFg: tone === 'neutral' ? 'var(--st-caption)' : (tone === 'warn' ? 'var(--st-accent-text)' : 'var(--ks3-ok-text)'),
        stBg: tone === 'neutral' ? 'var(--st-num-well)' : (tone === 'warn' ? 'var(--st-chip-tint)' : 'var(--ks3-ok-tint)'),
        stBc: tone === 'neutral' ? 'var(--st-rule-soft)' : (tone === 'warn' ? 'var(--st-chip-tint-border)' : 'var(--ks3-ok-tint)'),
        stDot: tone === 'neutral' ? 'var(--st-rule-strong)' : (tone === 'warn' ? 'var(--st-accent)' : 'var(--ks3-ok)'),
        stDotR: tone === 'warn' ? '1px' : '50%',
        open: () => this.setState({ screen: 'marking', paperId: p.id })
      };
    }) : [];

    const stMarked = stHistory.filter(h => h.marked);
    const stOnTime = stMarked.filter(h => !h.late).length;
    const stLate = stMarked.filter(h => h.late).length;
    const stMissing = stHistory.filter(h => h.missing).length;
    const stTimeSub = (stLate === 0 && stMissing === 0)
      ? 'Every deadline met'
      : [stLate ? (stLate === 1 ? '1 late' : stLate + ' late') : null, stMissing ? stMissing + ' not submitted' : null].filter(x => x).join(' · ');
    const stAvg = stMarked.length ? Math.round(stMarked.reduce((a, h) => a + h.pct, 0) / stMarked.length) : null;
    const dgMarkedSub = liveClasses.reduce((a, c) => a + this.matrixFor(c).markedSub, 0);
    const dgOnTime = liveClasses.reduce((a, c) => a + this.matrixFor(c).markedOnTime, 0);
    const dgLate = Math.max(0, dgMarkedSub - dgOnTime);
    const dgOnPct = dgMarkedSub ? Math.round((dgOnTime / dgMarkedSub) * 100) : 0;

    return {
      teacher,
      rowPad: compact ? '10px 18px' : '13px 18px',
      showMeter: meter,
      crumb: s.screen === 'classes' ? 'My classes' : (s.screen === 'import' ? 'Import' : (s.screen === 'digest' ? 'Digest' : (s.screen === 'insights' ? 'Insights' : k.code))),
      isClasses: s.screen === 'classes',
      isClass: s.screen === 'class',
      isStudent: s.screen === 'student',
      isMarking: s.screen === 'marking',
      isDigest: s.screen === 'digest',
      isImport: s.screen === 'import',
      classLine: teacher + ' · ' + this.CLASSES.length + ' classes · ' + totalStudents + ' students',
      shownLine: cards.length + ' shown',
      ksTabs: ['All', 'KS3', 'KS4'].map(t => ({ label: t, ...pill(s.ks === t), pick: () => this.setState({ ks: t }) })),
      sortTabs: [{ k: 'code', l: 'Class code' }, { k: 'activity', l: 'Most missing' }].map(o => ({
        label: o.l,
        fg: s.sort === o.k ? 'var(--st-ink)' : 'var(--st-caption)',
        bc: s.sort === o.k ? 'var(--st-btn-border)' : 'transparent',
        pick: () => this.setState({ sort: o.k })
      })),
      cards,
      klass: {
        code: k.code,
        subject: k.subject,
        dots: this.dotsFor(k.subject),
        longMeta: 'Year ' + k.year + ' · ' + k.ks + ' · 2026–27 · ' + k.n + ' students · ' + (kPapers.length ? kPapers.length + ' assignments' : 'no assignments'),
        rosterLine: k.n + ' active members',
        paperLine: kPapers.length ? kPapers.length + ' assignments' : 'None set',
        hasWork: kPapers.length > 0,
        noWork: kPapers.length === 0,
        noWorkLine: k.n + ' students are enrolled and waiting. Last activity ' + k.last + '.',
        tiles: kPapers.length ? (wPast ? [
          { label: 'Submitted', value: kMx.colSub[wi] + '/' + k.n, sub: wPaper.title },
          { label: 'Week mean', value: wMean == null ? '—' : wMean + '%', sub: wGap == null ? 'Nothing marked' : (wGap === 0 ? 'Level with the term average' : Math.abs(wGap) + (Math.abs(wGap) === 1 ? ' point ' : ' points ') + (wGap > 0 ? 'above' : 'below') + ' the term average') },
          { label: 'On time', value: kMx.colSub[wi] ? Math.round((kMx.colOnTime[wi] / kMx.colSub[wi]) * 100) + '%' : '—', sub: wLate + ' late of ' + kMx.colSub[wi] + ' submitted' },
          { label: 'Not submitted', value: String(k.n - kMx.colSub[wi]), sub: 'Of ' + k.n + ' students' }
        ] : [
          { label: 'This week', value: kMx.colSub[0] + '/' + k.n, sub: upcomingPaper ? upcomingPaper.title : '' },
          { label: 'Class mean', value: kMean == null ? '—' : kMean + '%', sub: 'Across ' + (kPapers.length - 1) + ' marked assignments' },
          { label: 'On time', value: kMx.markedPct == null ? '—' : kMx.markedPct + '%', sub: Math.max(0, kMx.markedSub - kMx.markedOnTime) + ' late of ' + kMx.markedSub + ' marked' },
          { label: 'Needs a look', value: String(flagged), sub: flagged ? 'Nothing in for two weeks' : 'Everyone accounted for' }
        ]) : [
          { label: 'This week', value: '—', sub: 'No work set' },
          { label: 'Class mean', value: '—', sub: 'Nothing marked yet' },
          { label: 'Students', value: String(k.n), sub: 'Roster imported' },
          { label: 'Last activity', value: k.last, sub: 'Revision, not homework' }
        ]
      },
      roster,
      weekTabs,
      weekNote,
      weekBack: () => { if (!backOff) this.pickWeek(wi + 1); },
      weekFwd: () => { if (!fwdOff) this.pickWeek(wi - 1); },
      weekBackColor: backOff ? 'var(--st-rule-strong)' : 'var(--st-ink)',
      weekFwdColor: fwdOff ? 'var(--st-rule-strong)' : 'var(--st-ink)',
      weekBackCursor: backOff ? 'default' : 'pointer',
      weekFwdCursor: fwdOff ? 'default' : 'pointer',
      rosterWeekCol: !kPapers.length ? 'This week' : (wPast ? wPaper.range : 'This week'),
      upcomingLabel: 'Upcoming ' + kPapers.filter(p => p.when === 'upcoming').length,
      markedLabel: 'Marked ' + kPapers.filter(p => p.when === 'marked').length,
      upcoming: kPapers.filter(p => p.when === 'upcoming').map(paperRow),
      marked: kPapers.filter(p => p.when === 'marked').map(paperRow),
      templates: this.TEMPLATES.map(t => ({
        label: t.label,
        fg: s.boTpl === t.id ? 'var(--st-accent-text)' : 'var(--st-ink)',
        bg: s.boTpl === t.id ? 'var(--st-chip-tint)' : 'var(--st-paper)',
        bc: s.boTpl === t.id ? 'var(--st-chip-tint-border)' : 'var(--st-btn-border)',
        pick: () => this.setState({ boTpl: t.id })
      })),
      feed: [
        {
          name: kRoster.length ? kRoster[Math.min(9, kRoster.length - 1)].name : '—',
          when: '2 days ago',
          template: 'Top of the class this week',
          body: 'Highest mean in ' + k.code + ' on the last set — and showed working on every question.'
        },
        {
          name: kRoster.length ? kRoster[Math.min(12, kRoster.length - 1)].name : '—',
          when: '1 week ago',
          template: 'Bounced back strong',
          body: 'Went from 38% to 74% after one reteach of the lowest-scoring question.'
        }
      ].map(f => ({ ...f, initials: this.initials(f.name), hue: this.hueFor(f.name) })),
      noteCount: (s.note || '').length + ' / 500',
      backToClass: 'Back to ' + k.code,
      student: {
        name: st ? st.name : '—',
        initials: st ? this.initials(st.name) : '',
        hue: st ? this.hueFor(st.name) : 'var(--st-rule-strong)',
        meta: k.code + ' · ' + k.subject + ' · Year ' + k.year + ' · ' + k.ks,
        subLine: stHistory.length + ' assignments',
        tiles: [
          { label: 'Submissions', value: String(stMarked.length), sub: 'Of ' + kPapers.length + ' set this term' },
          { label: 'On time', value: String(stOnTime), sub: stTimeSub },
          { label: 'Avg score', value: stAvg == null ? '—' : stAvg + '%', sub: 'Class mean ' + (kMean == null ? '—' : kMean + '%') },
          { label: 'Last active', value: st ? st.last : '—', sub: stHistory[0] && stHistory[0].status === 'In progress' ? stHistory[0].title : k.code + ' · ' + k.subject }
        ],
        history: stHistory
      },
      paper: pp ? {
        title: pp.title,
        eyebrow: k.code + ' · Set ' + pp.set + ' · Due ' + pp.due.replace('Due ', ''),
        tiles: [
          { label: 'Submitted', value: pp.sub, sub: pp.when === 'upcoming' ? 'Still open' : 'Marked automatically' },
          { label: 'Class mean', value: pp.mean, sub: '8 questions, 1 mark each' },
          { label: 'On time', value: pp.when === 'upcoming' ? '—' : String(kMx.colOnTime[pp.idx]), sub: pp.when === 'upcoming' ? 'Not due yet' : 'Late submissions still marked' },
          { label: 'Lowest', value: worst ? worst.id + ' · ' + worst.pct + '%' : '—', sub: worst ? worst.text : '' }
        ],
        questions: questions.map(qq => ({
          id: qq.id, text: qq.text, pct: qq.pct, label: qq.pct + '%',
          worst: worst && qq.id === worst.id,
          fill: qq.pct < 50 ? 'var(--st-accent)' : (qq.pct < 70 ? 'var(--st-hatch-b)' : 'var(--ks3-ok)')
        })),
        qids: questions.map(qq => ({ id: qq.id })),
        grid
      } : { title: '—', eyebrow: k.code, tiles: [], questions: [], qids: [], grid: [] },
      isInsights: s.screen === 'insights',
      insSub: chartScope === 'all'
        ? liveClasses.length + ' active classes · ' + totalStudents + ' students on roll'
        : k.code + ' · ' + k.n + ' students · ' + kPapers.length + ' assignments',
      insScopeTabs: [{ id: 'all', label: 'All classes' }, { id: k.id, label: k.code }].map(o => ({
        label: o.label,
        ...(chartScope === o.id
          ? { bg: 'var(--st-paper)', fg: 'var(--st-ink)', bc: 'var(--st-btn-border)' }
          : { bg: 'transparent', fg: 'var(--st-caption)', bc: 'transparent' }),
        pick: () => this.setState({ chartScope: o.id })
      })),
      insChips: this.CHART_KINDS.map(o => ({
        label: o.label,
        fg: chartKind === o.id ? 'var(--st-paper)' : 'var(--st-ink)',
        bg: chartKind === o.id ? 'var(--st-accent-text)' : 'var(--st-paper)',
        bc: chartKind === o.id ? 'var(--st-accent-text)' : 'var(--st-btn-border)',
        pick: () => this.setState({ chartKind: o.id })
      })),
      chart: {
        ...chart,
        isBars: chart.type === 'bars',
        isCols: chart.type === 'cols',
        isStack: chart.type === 'stack',
        hasLegend: chart.legend.length > 0,
        scopeLabel: chartScope === 'all' ? 'All classes' : k.code
      },
      openInsights: () => this.setState({
        screen: 'insights',
        insFrom: s.screen === 'class' ? 'class' : 'classes',
        chartScope: s.screen === 'class' ? k.id : chartScope
      }),
      goBackFromInsights: () => this.setState({ screen: s.insFrom || 'classes' }, () => { if ((s.insFrom || 'classes') === 'class') this.snapWeekRail(); }),
      digestTitle: isClassReport ? k.code + ' report' : 'Weekly digest',
      digestTableTitle: isClassReport ? 'By assignment' : 'By class',
      digestColTitle: isClassReport ? 'Assignment' : 'Class',
      digestSub: isClassReport
        ? k.n + ' students · ' + kPapers.length + ' assignments this term'
        : this.CLASSES.length + ' classes · ' + totalStudents + ' students · ' + totalSubs + ' submissions',
      digestTiles: isClassReport ? [
        { label: 'Submissions', value: kMx.colSub[0] + '/' + k.n, sub: 'This week' },
        { label: 'Class mean', value: kMean == null ? '—' : kMean + '%', sub: 'Across ' + Math.max(0, kPapers.length - 1) + ' marked assignments' },
        { label: 'On time', value: kMx.markedPct == null ? '—' : kMx.markedPct + '%', sub: Math.max(0, kMx.markedSub - kMx.markedOnTime) + ' late of ' + kMx.markedSub + ' marked' },
        { label: 'Needs a look', value: String(kFlagged), sub: kFlagged ? 'Nothing in for two weeks' : 'Everyone accounted for' }
      ] : [
        { label: 'Submissions', value: String(totalSubs), sub: 'Across ' + liveClasses.length + ' active classes' },
        { label: 'Mean score', value: Math.round(liveClasses.reduce((a, c) => a + (this.meanOf(c) || 0), 0) / liveClasses.length) + '%', sub: 'Mean of ' + liveClasses.length + ' class means' },
        { label: 'On time', value: dgOnPct + '%', sub: dgLate + ' late of ' + dgMarkedSub + ' marked submissions' },
        { label: 'Needs a look', value: String(liveClasses.reduce((a, c) => a + this.rosterFor(c).filter(r => r.flag).length, 0)), sub: 'Students with nothing in' }
      ],
      digestRows: isClassReport ? classReportRows : digestRows,
      importSteps: [1, 2, 3].map(n => {
        const on = s.importStep === n;
        const done = s.importStep > n;
        return {
          n: String(n), label: ['Upload', 'Map columns', 'Confirm'][n - 1],
          bg: on ? 'var(--st-paper)' : 'transparent',
          bc: on ? 'var(--st-edge)' : 'var(--st-rule-soft)',
          fg: on || done ? 'var(--st-ink)' : 'var(--st-caption)',
          numBg: on ? 'var(--st-accent-text)' : 'var(--st-num-well)',
          numFg: on ? 'var(--st-paper)' : 'var(--st-caption)'
        };
      }),
      imp1: s.importStep === 1,
      imp2: s.importStep === 2,
      imp3: s.importStep === 3,
      mapRows: [
        { col: 'first_name', field: 'First name', note: 'Matched', noteFg: 'var(--ks3-ok-text)' },
        { col: 'surname', field: 'Last name', note: 'Matched', noteFg: 'var(--ks3-ok-text)' },
        { col: 'school_email', field: 'Email', note: 'Matched', noteFg: 'var(--ks3-ok-text)' },
        { col: 'yr', field: 'Year group', note: 'Guessed from header', noteFg: 'var(--st-muted)' },
        { col: 'form', field: 'Ignored', note: 'Not used by Mr Badmus AI', noteFg: 'var(--st-ghost)' }
      ],
      previewRows: [
        { name: 'Aisha Bello', email: 'a.bello@school.uk', klass: '8r/Sc4', status: 'New', stFg: 'var(--ks3-ok-text)' },
        { name: 'Tom Okri', email: 't.okri@school.uk', klass: '8r/Sc4', status: 'New', stFg: 'var(--ks3-ok-text)' },
        { name: 'Daisy Fairhurst', email: 'd.fairhurst@school.uk', klass: '8r/Sc1', status: 'Already enrolled', stFg: 'var(--st-muted)' },
        { name: 'J. Smith', email: 'missing', klass: '8r/Sc4', status: 'Email missing', stFg: 'var(--st-accent-text)' }
      ],
      setWorkOpen: s.modal === 'setwork',
      bulkOpen: s.modal === 'bulk',
      searchOpen: s.modal === 'search',
      sw1: s.swStep === 1, sw2: s.swStep === 2, sw3: s.swStep === 3,
      swEyebrow: 'Step ' + s.swStep + ' of 3 · ' + ['Topic', 'Detail', 'Classes'][s.swStep - 1],
      topics: this.TOPICS.map(t => ({
        name: t.name, unit: t.unit, tag: t.tag,
        bg: s.swTopic === t.id ? 'var(--st-chip-tint)' : 'var(--st-paper)',
        bc: s.swTopic === t.id ? 'var(--st-chip-tint-border)' : 'var(--st-btn-border)',
        tagFg: s.swTopic === t.id ? 'var(--st-accent-text)' : 'var(--st-ghost)',
        pick: () => this.setState({ swTopic: t.id })
      })),
      swCounts: [6, 10, 15].map(n => ({
        label: n + ' Q',
        fg: s.swQ === n ? 'var(--st-accent-text)' : 'var(--st-ink)',
        bg: s.swQ === n ? 'var(--st-chip-tint)' : 'var(--st-paper)',
        bc: s.swQ === n ? 'var(--st-chip-tint-border)' : 'var(--st-btn-border)',
        pick: () => this.setState({ swQ: n })
      })),
      swDays: ['Mon', 'Tue', 'Wed', 'Thu', 'Fri'].map(d => ({
        label: d,
        fg: s.swDay === d ? 'var(--st-accent-text)' : 'var(--st-ink)',
        bg: s.swDay === d ? 'var(--st-chip-tint)' : 'var(--st-paper)',
        bc: s.swDay === d ? 'var(--st-chip-tint-border)' : 'var(--st-btn-border)',
        pick: () => this.setState({ swDay: d })
      })),
      swRelease: [{ k: 'now', l: 'Release now' }, { k: 'lesson', l: 'Release next lesson' }].map(o => ({
        label: o.l,
        fg: s.swRel === o.k ? 'var(--st-accent-text)' : 'var(--st-ink)',
        bg: s.swRel === o.k ? 'var(--st-chip-tint)' : 'var(--st-paper)',
        bc: s.swRel === o.k ? 'var(--st-chip-tint-border)' : 'var(--st-btn-border)',
        pick: () => this.setState({ swRel: o.k })
      })),
      swClassList: this.CLASSES.filter(c => c.n > 0).map(c => {
        const on = swSel.indexOf(c.id) > -1;
        return {
          code: c.code, sub: c.subject + ' · ' + c.n + ' students',
          bg: on ? 'var(--st-chip-tint)' : 'var(--st-paper)',
          bc: on ? 'var(--st-chip-tint-border)' : 'var(--st-btn-border)',
          boxBg: on ? 'var(--st-accent-text)' : 'transparent',
          boxBc: on ? 'var(--st-accent-text)' : 'var(--st-rule-strong)',
          toggle: () => this.setState({ swClasses: on ? swSel.filter(x => x !== c.id) : swSel.concat([c.id]) })
        };
      }),
      swSummary: s.swStep === 3
        ? swSel.length + ' classes · ' + swStudents + ' students'
        : topic.name + ' · ' + s.swQ + ' questions · due ' + s.swDay,
      swBackLabel: s.swStep === 1 ? 'Cancel' : 'Back',
      swNextLabel: s.swStep === 3 ? 'Set work' : 'Next',
      swBack: () => s.swStep === 1 ? this.setState({ modal: null }) : this.setState({ swStep: s.swStep - 1 }),
      swNext: () => {
        if (s.swStep < 3) return this.setState({ swStep: s.swStep + 1 });
        this.setState({ modal: null, swStep: 1 });
        this.ping(topic.name + ' set for ' + swSel.length + ' classes · ' + swStudents + ' students');
      },
      bulkStudents: kRoster.map(r => {
        const on = s.boSel.indexOf(r.id) > -1;
        return {
          name: r.name,
          fg: on ? 'var(--st-accent-text)' : 'var(--st-ink)',
          bg: on ? 'var(--st-chip-tint)' : 'var(--st-paper)',
          bc: on ? 'var(--st-chip-tint-border)' : 'var(--st-btn-border)',
          dot: on ? 'var(--st-accent)' : this.hueFor(r.name),
          toggle: () => this.setState({ boSel: on ? s.boSel.filter(x => x !== r.id) : s.boSel.concat([r.id]) })
        };
      }),
      bulkSummary: s.boSel.length + ' selected · ' + (this.TEMPLATES.filter(t => t.id === s.boTpl)[0] || { label: 'no template' }).label,
      bulkTop: () => this.setState({ boSel: kRoster.filter(r => r.inWeek).map(r => r.id) }),
      sendBulk: () => {
        const n = s.boSel.length;
        this.setState({ modal: null, boSel: [] });
        this.ping(n ? 'Shoutout sent to ' + n + ' students' : 'Pick at least one student');
      },
      searchResults: results,
      searchFoot: results.length + ' of ' + pool.length + ' students · type to narrow',
      setSearch: (e) => this.setState({ search: e.target.value }),
      pickRecipient: (e) => this.setState({ recipient: e.target.value }),
      setNote: (e) => this.setState({ note: e.target.value }),
      sendShoutout: () => this.ping(s.recipient ? 'Shoutout sent to ' + s.recipient : 'Pick a student first'),
      hasToast: !!s.toast,
      toast: s.toast,
      goClasses: () => this.setState({ screen: 'classes', modal: null }),
      goClass: () => this.setState({ screen: 'class', modal: null }, () => this.snapWeekRail()),
      goDigest: () => this.setState({ screen: 'digest', digestScope: 'all' }),
      goReport: () => this.setState({ screen: 'digest', digestScope: 'class' }),
      goImport: () => this.setState({ screen: 'import', importStep: 1 }),
      goBackFromDigest: () => this.setState({ screen: s.digestScope === 'class' ? 'class' : 'classes' }, () => { if (s.digestScope === 'class') this.snapWeekRail(); }),
      doPrint: () => window.print(),
      openSearch: () => this.setState({ modal: 'search', search: '' }),
      openSetWork: () => this.setState({ modal: 'setwork', swStep: 1, swClasses: [k.id] }),
      openBulk: () => this.setState({ modal: 'bulk' }),
      closeModal: () => this.setState({ modal: null }),
      stop: (e) => e.stopPropagation(),
      impNext: () => this.setState({ importStep: Math.min(3, s.importStep + 1) }),
      impBack: () => this.setState({ importStep: Math.max(1, s.importStep - 1) }),
      impDone: () => { this.setState({ screen: 'classes', importStep: 1 }); this.ping('26 students imported into 8r/Sc4'); },
      sampleCsv: () => this.ping('Template CSV downloaded'),
      pastYears: () => this.ping('2025–26 is read-only')
    };
  }
}

